DO $$
DECLARE
  mapping jsonb := '{"/__l5e/assets-v1/0c287bea-1b9d-4c04-becd-8ef659f40519/yamaha-nmax.png": "/__l5e/assets-v1/952c7b9b-8452-4558-bea2-517d04df8793/yamaha-nmax-nobg.png", "/__l5e/assets-v1/113bc4f1-3d5c-4fb0-92af-dce0212f372d/yamaha-aerox.png": "/__l5e/assets-v1/43fb8e74-39a1-4136-b2ec-b3557d7a15cf/yamaha-aerox-nobg.png", "/__l5e/assets-v1/230812e9-36a7-42d0-8abe-6cf51c506dfa/neos-eblack.jpg": "/__l5e/assets-v1/5d3e14f4-5bb1-44fb-bf7f-387646783240/neos-eblack-nobg.png", "/__l5e/assets-v1/311e166d-8078-444f-a855-d64c64334fcc/yamaha-fz25.png": "/__l5e/assets-v1/35b4ff7c-1209-4ecc-9f1d-b7c62e55065f/yamaha-fz25-nobg.png", "/__l5e/assets-v1/4107a333-d6b1-4a04-a0c8-f5c875f618d5/yamaha-factor-150.png": "/__l5e/assets-v1/62a8ec25-0a87-4067-b61a-7e42a8e3809a/yamaha-factor-150-nobg.png", "/__l5e/assets-v1/68ab15c5-a2b3-4720-b4ce-3d4fc5e46445/yamaha-xmax.png": "/__l5e/assets-v1/a3ad9603-590e-43fe-bbc8-433ed298e7c8/yamaha-xmax-nobg.png", "/__l5e/assets-v1/68bc708f-0fb6-426f-9118-11c048fbe4c0/yamaha-fluo-hybrid.png": "/__l5e/assets-v1/5e2ae4fe-6ac8-445a-8953-1713943624c2/yamaha-fluo-hybrid-nobg.png", "/__l5e/assets-v1/d8a1fec0-5f1f-49da-bf08-53c62c19928f/neos-ewhite.jpg": "/__l5e/assets-v1/e50c1c36-84e4-4b5a-b5f1-c567614aae0e/neos-ewhite-nobg.png", "/__l5e/assets-v1/e1641849-233f-4f19-982c-3f3d1b7844f4/yamaha-rayzr-hybrid.png": "/__l5e/assets-v1/23bd0443-c9ef-4c04-82a1-206561fc4d7d/yamaha-rayzr-hybrid-nobg.png", "/__l5e/assets-v1/f864f72f-c8df-4a5b-a47e-84e53d6773ca/yamaha-factor-150-dx.png": "/__l5e/assets-v1/d63cd06b-109a-4e8a-be37-1d6ba1a68743/yamaha-factor-150-dx-nobg.png", "https://yamahamotors.fbitsstatic.net/img/p/crosser-150-s-abs-151343/340245-1.jpg": "/__l5e/assets-v1/580e2a3f-12b9-4190-9a6b-9dd9299e32a7/340245-1-nobg.png", "https://yamahamotors.fbitsstatic.net/img/p/crosser-150-z-abs-150320/337234-1.jpg": "/__l5e/assets-v1/2b471942-e7b4-4e57-a7c5-ad8db836f198/337234-1-nobg.png", "https://yamahamotors.fbitsstatic.net/img/p/fazer-fz15-abs-connected-2026-151299/339824-1