50f-2025-156727/360221-1.jpg": "/__l5e/assets-v1/44371e69-e02e-4706-a0ab-c08624cd4953/360221-1-nobg.png", "https://yamahamotors.fbitsstatic.net/img/p/wr450f-2025-156852/360463-1.jpg": "/__l5e/assets-v1/4454d829-5840-490c-babf-fdb7ce6f1a29/360463-1-nobg.png", "https://yamahamotors.fbitsstatic.net/img/p/yz125-2025-157094/361839-1.jpg": "/__l5e/assets-v1/d5f9dc65-f7d9-48fb-bd31-94adfc7ea436/361839-1-nobg.png", "https://yamahamotors.fbitsstatic.net/img/p/yz250-150321/337235-1.jpg": "/__l5e/assets-v1/d8c9c95e-b217-4efa-b967-a5b433b13449/337235-1-nobg.png", "https://yamahamotors.fbitsstatic.net/img/p/yz250f-2025-157217/362187-1.jpg": "/__l5e/assets-v1/444b757a-4c4e-4b90-b12d-463262a97b71/362187-1-nobg.png", "https://yamahamotors.fbitsstatic.net/img/p/yz450f-157341/362428-1.jpg": "/__l5e/assets-v1/f798d797-ed55-4abd-998f-421470144c98/362428-1-nobg.png", "https://yamahamotors.fbitsstatic.net/img/p/yz65-150291/337201-1.jpg": "/__l5e/assets-v1/fa259e8c-f027-4f51-91a6-a268b45138e2/337201-1-nobg.png", "https://yamahamotors.fbitsstatic.net/img/p/yz85lw-150322/337236-1.jpg": "/__l5e/assets-v1/063c7b3a-5b76-402d-bec1-79ba51791761/337236-1-nobg.png"}'::jsonb;
  r record;
  c jsonb;
  arr jsonb;
BEGIN
  FOR r IN SELECT id, colors FROM public.models WHERE brand='yamaha' AND is_active=true LOOP
    arr := '[]'::jsonb;
    FOR c IN SELECT jsonb_array_elements(r.colors) LOOP
      IF c ? 'image' AND mapping ? (c->>'image') THEN
        c := jsonb_set(c, '{image}', mapping->(c->>'image'));
      END IF;
      arr := arr || jsonb_build_array(c);
    END LOOP;
    UPDATE public.models SET colors = arr, updated_at = now() WHERE id = r.id;
  END LOOP;
END $$;